const rosterRows = $('Read Staff Roster').all().map(i => i.json);
const staffingRows = $('Read Session Staffing Map').all().map(i => i.json);
const ruleRows = $('Load Coverage Rules').all().map(i => i.json);
const sessions = $input.all().map(i => i.json);

function parseDateOnly(value) {
  if (value === null || value === undefined || value === '') return null;
  if (typeof value === 'number' && isFinite(value)) {
    const serial = DateTime.fromObject({ year: 1899, month: 12, day: 30 }).plus({ days: Math.floor(value) });
    return serial.isValid ? serial.startOf('day') : null;
  }
  const text = String(value).trim();
  const attempts = [
    DateTime.fromISO(text, { setZone: true }),
    DateTime.fromFormat(text, 'yyyy-MM-dd'),
    DateTime.fromFormat(text, 'M/d/yyyy'),
    DateTime.fromFormat(text, 'MMM d, yyyy'),
    DateTime.fromFormat(text, 'd-MMM-yyyy')
  ];
  for (const dt of attempts) {
    if (dt.isValid) return dt.startOf('day');
  }
  const js = DateTime.fromJSDate(new Date(text));
  return js.isValid ? js.startOf('day') : null;
}

const clean = v => String(v === null || v === undefined ? '' : v).trim();

const roster = {};
for (const row of rosterRows) {
  const person = clean(row.Person !== undefined ? row.Person : row.person);
  const cert = clean(row.Certification !== undefined ? row.Certification : row.certification);
  if (!person || !cert) continue;
  if (!roster[person]) roster[person] = { email: '', certs: {} };
  const email = clean(row.Email !== undefined ? row.Email : row.email);
  if (email) roster[person].email = email;
  const expiryRaw = row.Expiry !== undefined ? row.Expiry : row.expiry;
  roster[person].certs[cert.toLowerCase()] = { label: cert, expiry: parseDateOnly(expiryRaw), expiryRaw: clean(expiryRaw) };
}

const staffing = {};
for (const row of staffingRows) {
  const code = clean(row.SessionCode !== undefined ? row.SessionCode : row.sessionCode).toUpperCase();
  const person = clean(row.Person !== undefined ? row.Person : row.person);
  if (!code || !person) continue;
  if (!staffing[code]) staffing[code] = [];
  if (!staffing[code].includes(person)) staffing[code].push(person);
}

const rules = {};
for (const row of ruleRows) {
  const type = clean(row.session_type).toUpperCase();
  if (!type) continue;
  rules[type] = { requiredCert: clean(row.required_cert), minCertified: Number(row.min_certified) || 0 };
}

const results = [];
for (const s of sessions) {
  const base = {
    eventId: s.eventId || '',
    sessionTitle: s.sessionTitle || '(untitled event)',
    sessionCode: s.sessionCode || '',
    sessionDateIso: '',
    status: '',
    reasonText: '',
    requiredCert: '',
    minRequired: 0,
    assignedCount: 0,
    certifiedCount: 0,
    shortfall: 0,
    lapsed: [],
    fixPlan: [],
    fixSummary: '',
    renewBy: ''
  };
  const sessionDate = parseDateOnly(s.sessionStartRaw);
  base.sessionDateIso = sessionDate ? sessionDate.toISODate() : clean(s.sessionStartRaw);
  if (!s.sessionCode) {
    base.status = 'unmatched';
    base.reasonText = 'no [CODE] token found in the event title';
    results.push(base);
    continue;
  }
  const type = s.sessionCode.split('-')[0];
  const rule = rules[type];
  if (!rule) {
    base.status = 'unmatched';
    base.reasonText = 'no rule for session type ' + type + ' in the rules Data Table';
    results.push(base);
    continue;
  }
  const assigned = staffing[s.sessionCode] || [];
  if (assigned.length === 0) {
    base.status = 'unmatched';
    base.reasonText = 'no staffing rows for code ' + s.sessionCode + ' in the Staffing tab';
    results.push(base);
    continue;
  }
  if (!sessionDate) {
    base.status = 'unmatched';
    base.reasonText = 'could not parse the session start date';
    results.push(base);
    continue;
  }
  base.requiredCert = rule.requiredCert;
  base.minRequired = rule.minCertified;
  base.assignedCount = assigned.length;
  base.renewBy = sessionDate.toISODate();
  const sessionDateIso = sessionDate.toISODate();
  const lapsed = [];
  let certifiedCount = 0;
  for (const person of assigned) {
    const entry = roster[person];
    const cert = entry ? entry.certs[rule.requiredCert.toLowerCase()] : undefined;
    if (cert && cert.expiry && cert.expiry.toISODate() >= sessionDateIso) {
      certifiedCount += 1;
    } else {
      let expiredOn = 'person not on roster';
      if (entry) {
        if (cert && cert.expiry) expiredOn = cert.expiry.toISODate();
        else if (cert) expiredOn = 'unparseable date: ' + cert.expiryRaw;
        else expiredOn = 'cert not on roster';
      }
      lapsed.push({
        person: person,
        email: entry ? entry.email : '',
        cert: rule.requiredCert,
        expiredOn: expiredOn,
        renewable: Boolean(cert && cert.expiry)
      });
    }
  }
  base.certifiedCount = certifiedCount;
  base.lapsed = lapsed;
  const shortfall = Math.max(0, rule.minCertified - certifiedCount);
  base.shortfall = shortfall;
  if (shortfall === 0) {
    base.status = 'covered';
    results.push(base);
    continue;
  }
  base.status = 'under_covered';
  const renewable = lapsed.filter(l => l.renewable).sort((a, b) => (a.expiredOn < b.expiredOn ? 1 : -1));
  const picks = renewable.slice(0, shortfall).map(l => ({ person: l.person, email: l.email, cert: l.cert, expiredOn: l.expiredOn, renewBy: base.renewBy }));
  base.fixPlan = picks;
  const parts = picks.map(p => 'renew ' + p.person + ' (' + p.cert + ', expired ' + p.expiredOn + ')');
  let summary = parts.length ? parts.join('; ') + ' by ' + base.renewBy : '';
  const stillShort = shortfall - picks.length;
  if (stillShort > 0) {
    summary += (summary ? '. ' : '') + 'Renewals alone cannot close the gap: assign ' + stillShort + ' more ' + rule.requiredCert + ' holder(s)';
  }
  base.fixSummary = summary;
  results.push(base);
}

return results.map(r => ({ json: r }));

const cfg = $('Workflow Configuration').first().json;
const lines = $input.all().map(i => i.json);
const fixes = lines.filter(l => l.lineType === 'fix');
const warns = lines.filter(l => l.lineType === 'unmatched');
const oks = lines.filter(l => l.lineType === 'covered');

const out = [];
out.push(':radar: *Certification Lapse Radar*: next ' + cfg.lookaheadWeeks + ' weeks, ' + lines.length + ' session(s) checked.');
out.push('');
if (fixes.length) {
  out.push('*Under covered sessions (' + fixes.length + ')*');
  for (const l of fixes) out.push(l.reportLine);
  out.push('');
}
if (warns.length) {
  out.push('*Unmatched calendar events (' + warns.length + ')*');
  out.push('These events could not be joined to staffing and rules, so they were NOT validated. Fix the [CODE] token in the event title, the Staffing tab, or the rules Data Table.');
  for (const l of warns) out.push(l.reportLine);
  out.push('');
}
if (!fixes.length && !warns.length) {
  out.push(':white_check_mark: All clear. Every matched session meets its certified headcount on the session date.');
  out.push('');
}
out.push('Fully covered sessions: ' + oks.length + '.');

return [{ json: { slackText: out.join('\n'), fixCount: fixes.length, unmatchedCount: warns.length, coveredCount: oks.length } }];

const sessions = $('Validate Certs On Session Date').all().map(i => i.json);
const byKey = {};
for (const s of sessions) {
  if (s.status !== 'under_covered' && s.status !== 'covered') continue;
  for (const l of (s.lapsed || [])) {
    if (!l.email || !l.renewable) continue;
    const key = l.person + '|' + l.cert;
    if (!byKey[key]) {
      byKey[key] = { person: l.person, email: l.email, cert: l.cert, expiredOn: l.expiredOn, sessions: [] };
    }
    byKey[key].sessions.push({ code: s.sessionCode, date: s.sessionDateIso });
  }
}
const notices = Object.values(byKey).map(n => {
  const sorted = n.sessions.slice().sort((a, b) => (a.date < b.date ? -1 : 1));
  return {
    person: n.person,
    email: n.email,
    cert: n.cert,
    expiredOn: n.expiredOn,
    sessionCount: sorted.length,
    sessionList: sorted.map(x => x.code + ' on ' + x.date).join('; '),
    renewBy: sorted.length ? sorted[0].date : ''
  };
});
return notices.map(n => ({ json: n }));
